import{c as s,Q as i,j as a,m as o}from"./chunks/framework.ByJJFMw8.js";const g=JSON.parse('{"title":"RAG、微调、续训与智能体选型（知识点笔记）","description":"","frontmatter":{},"headers":[],"relativePath":"posts/llm/RAG微调续训与智能体选型知识点笔记.md","filePath":"posts/llm/RAG微调续训与智能体选型知识点笔记.md","lastUpdated":null}'),n={name:"posts/llm/RAG微调续训与智能体选型知识点笔记.md"};function r(l,t,e,d,h,p){return i(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="rag、微调、续训与智能体选型-知识点笔记" tabindex="-1">RAG、微调、续训与智能体选型（知识点笔记） <a class="header-anchor" href="#rag、微调、续训与智能体选型-知识点笔记" aria-label="Permalink to &quot;RAG、微调、续训与智能体选型（知识点笔记）&quot;">​</a></h1><blockquote><p>来源：<a href="https://didilili.github.io/ai-agents-from-zero/#/1-3-RAG%E3%80%81%E5%BE%AE%E8%B0%83%E3%80%81%E7%BB%AD%E8%AE%AD%E4%B8%8E%E6%99%BA%E8%83%BD%E4%BD%93%E9%80%89%E5%9E%8B" target="_blank" rel="noreferrer">ai-agents-from-zero 第 1-3 章《RAG、微调、续训与智能体选型》</a>（<a href="https://github.com/didilili/ai-agents-from-zero" target="_blank" rel="noreferrer">GitHub 仓库</a>），原文配图与完整讲解见原站。整理于 2026-11-26。</p></blockquote><p>五大工程模块中，提示词工程（1-2）之外的后四项——RAG、微调、续训、智能体——表面都在&quot;增强模型能力&quot;，实际解决的问题并不一样。本文提炼本章的选型地图与最值得记的知识点。</p><h2 id="一、先诊断-再选型-四问定位根因" tabindex="-1">一、先诊断，再选型：四问定位根因 <a class="header-anchor" href="#一、先诊断-再选型-四问定位根因" aria-label="Permalink to &quot;一、先诊断，再选型：四问定位根因&quot;">​</a></h2><p>真实项目里 AI 应用回答不好时，最忌讳&quot;还没判断根因就说&#39;要不要微调&#39;&#39;要不要上 Agent&#39;&quot;。先问四个问题：</p><table tabindex="0"><thead><tr><th>诊断问题</th><th>常见现象</th><th>优先考虑</th></tr></thead><tbody><tr><td>模型是不是没看到资料？</td><td>不知道公司制度、产品手册、最新公告，回答无引用依据</td><td>RAG</td></tr><tr><td>模型是不是行为不稳定？</td><td>格式飘、话术不统一、分类标签不稳、JSON 经常错</td><td>Prompt 优化，必要时微调</td></tr><tr><td>模型是不是不懂领域语言分布？</td><td>拿到资料也读不懂，专业术语和行业逻辑经常错</td><td>续训，通常再配合 RAG</td></tr><tr><td>任务是不是需要多步执行？</td><td>需要查资料、调接口、校验、重试、写入系统</td><td>工作流或 Agent</td></tr></tbody></table><blockquote><p>判断方案的三条主线：**知识够不够、行为稳不稳、流程会不会动。**缺知识先看 RAG；缺输出风格、格式、指令遵循先看微调；缺领域底层语言能力才考虑续训；缺多步决策与工具调用再看智能体。</p></blockquote><h2 id="二、选型总顺序-成本从低到高" tabindex="-1">二、选型总顺序：成本从低到高 <a class="header-anchor" href="#二、选型总顺序-成本从低到高" aria-label="Permalink to &quot;二、选型总顺序：成本从低到高&quot;">​</a></h2><ol><li><strong>先 Prompt</strong>：只是需求表达不清，先把输入、输出、约束写清楚；</li><li><strong>再 RAG</strong>：缺资料、依据、最新信息或私有知识，优先建知识库；</li><li><strong>再微调</strong>：长期行为不稳，且已有高质量样本和评测标准；</li><li><strong>慎用续训</strong>：仅当模型对领域语言和知识分布系统性陌生；</li><li><strong>流程固定先工作流</strong>：步骤明确、需要稳定可审计；</li><li><strong>流程开放再 Agent</strong>：步骤会变、需要动态选工具、按中间结果调整路线。</li></ol><blockquote><p>后面的方案不是&quot;更高级&quot;，只是成本、风险和维护压力更高。能用轻方案稳定解决的问题，就不要过早引入重方案。</p></blockquote><h2 id="三、rag-先查资料-再回答问题" tabindex="-1">三、RAG：先查资料，再回答问题 <a class="header-anchor" href="#三、rag-先查资料-再回答问题" aria-label="Permalink to &quot;三、RAG：先查资料，再回答问题&quot;">​</a></h2><ul><li><strong>最短定义</strong>：RAG = 先查资料，再回答问题。流程：提问 → 去外部知识库检索 → 把&quot;问题 + 检索结果&quot;一起发给模型 → 生成答案。重点不是改模型参数，而是<strong>在运行时给模型补上下文</strong>。</li><li><strong>与提示词工程的区别</strong>：Prompt 依赖提前写好的提示词，RAG 依赖提问时实时检索到的外部资料。</li><li><strong>为什么常是第一选择</strong>：大模型答不好的三类真实成因——<strong>知识过时、知识私有、证据不足</strong>——本质都是&quot;模型没看到材料&quot;而非&quot;不会说话&quot;。RAG 优势：更新快（改知识库即可）、成本低、可追溯（保留来源/页码/文件名）、贴近业务系统。</li></ul><p><strong>两阶段工作流程</strong>：</p><table tabindex="0"><thead><tr><th>阶段</th><th>步骤</th></tr></thead><tbody><tr><td>索引（离线）</td><td>读文档 → 清洗切分 → 嵌入模型转向量 → 文本块 + 向量 + 元数据写入向量库</td></tr><tr><td>问答（在线）</td><td>问题向量化 → 召回相关片段 → 组装进 Prompt → 模型生成最终回答</td></tr></tbody></table><blockquote><p>RAG 从来不只是&quot;向量库 + 大模型&quot;。文档质量、分块策略、召回方式、重排策略、Prompt 组织方式，都会影响最终效果。</p></blockquote><h2 id="四、rag-的四个常见误区与排查链路" tabindex="-1">四、RAG 的四个常见误区与排查链路 <a class="header-anchor" href="#四、rag-的四个常见误区与排查链路" aria-label="Permalink to &quot;四、RAG 的四个常见误区与排查链路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>纠正</th></tr></thead><tbody><tr><td>有知识库就一定不会幻觉</td><td>只能显著降低：检索错、噪声多、Prompt 没约束好仍会答错</td></tr><tr><td>文档全塞进去就行</td><td>关键不是数量多，而是&quot;能不能把相关的那几段稳稳找出来&quot;</td></tr><tr><td>RAG = 向量检索</td><td>真实项目常结合关键词检索、过滤、重排、元数据约束</td></tr><tr><td>RAG 能替代一切训练</td><td>只解决&quot;没看到知识&quot;，不解决&quot;不会按固定风格/格式输出&quot;</td></tr></tbody></table><p>效果不理想时沿链路排查（从轻到重）：<strong>文档质量 → 文档解析 → 文本切分</strong>（chunk size / overlap / 按标题层级）<strong>→ 召回策略</strong>（Embedding / Top-K / 元数据过滤）<strong>→ 重排序</strong>（Reranker）<strong>→ Prompt 增强</strong>（要求引用资料、缺依据时说&quot;不确定&quot;）<strong>→ 生成模型</strong>。</p><blockquote><p><strong>RAG 失败先修检索链路，再看生成模型；不要把所有问题都归因于&quot;模型不够强&quot;。</strong></p></blockquote><h2 id="五、微调-改模型的-行为方式-不是灌知识" tabindex="-1">五、微调：改模型的&quot;行为方式&quot;，不是灌知识 <a class="header-anchor" href="#五、微调-改模型的-行为方式-不是灌知识" aria-label="Permalink to &quot;五、微调：改模型的&quot;行为方式&quot;，不是灌知识&quot;">​</a></h2><ul><li><strong>定位</strong>：微调在已训练好的基础模型上用特定数据继续训练，让模型在某类任务/风格/输出形式上更稳定。它改的是&quot;行为方式&quot;，不是外挂知识库——<strong>不适合承载高频变化的知识</strong>，知识常变仍优先 RAG。</li><li><strong>何时需要</strong>：① 行为不稳定（JSON/SQL/分类标签飘、多轮提示仍漏字段漏步骤）；② 风格话术需长期固化（客服口吻、报告规范、品牌语气）；③ Prompt 已反复优化但仍不稳。</li><li><strong>何时可以微调（前提）</strong>：数据足够（高质量、任务相关、标注明确，否则是&quot;把噪声训练进模型&quot;）；评测标准清楚（先做评测集和验收标准，再谈训练）；算力与预算可接受。</li></ul><p><strong>技术方法</strong>：</p><table tabindex="0"><thead><tr><th>方法</th><th>思路</th></tr></thead><tbody><tr><td>全参数微调</td><td>更新全部参数，上限高但资源/显存开销大</td></tr><tr><td>LoRA</td><td>冻结原模型大部分参数，只训新增的低秩适配参数</td></tr><tr><td>QLoRA</td><td>LoRA + 低比特量化，进一步降低显存</td></tr><tr><td>Adapter / Prefix / P-Tuning v2</td><td>层间插适配器 / 可学习虚拟前缀 / 每层可训练提示向量</td></tr></tbody></table><blockquote><p>工程认知：今天大多数团队自己做微调，优先考虑的不是全参，而是 <strong>LoRA / QLoRA 这类 PEFT 路线</strong>。</p></blockquote><p><strong>主要风险</strong>：过拟合（训练集很好、真实场景拉胯）、灾难性遗忘（学新任务冲掉原有能力）、样本偏差（把团队偏见和噪声学进去）、评测幻觉（只看少量样例就下结论）。微调前后都要自问：我解决的是长期、稳定、可评测的行为问题，还是只是觉得 Prompt 不顺手？</p><h2 id="六、rag-vs-微调-缺知识看-rag-缺行为看微调" tabindex="-1">六、RAG vs 微调：缺知识看 RAG，缺行为看微调 <a class="header-anchor" href="#六、rag-vs-微调-缺知识看-rag-缺行为看微调" aria-label="Permalink to &quot;六、RAG vs 微调：缺知识看 RAG，缺行为看微调&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>RAG</th><th>微调</th></tr></thead><tbody><tr><td>核心目标</td><td>给模型补充外部知识</td><td>让模型更稳定地按目标做事</td></tr><tr><td>是否修改参数</td><td>否</td><td>是</td></tr><tr><td>擅长解决</td><td>私有知识、最新知识、可追溯</td><td>风格、格式、指令遵循、分类</td></tr><tr><td>更新速度</td><td>快，改知识库即可</td><td>慢，需重新训练</td></tr><tr><td>成本结构</td><td>系统开发成本为主</td><td>数据、训练、评测成本为主</td></tr><tr><td>典型场景</td><td>文档问答、知识库、客服知识</td><td>结构化输出、统一话术</td></tr></tbody></table><h2 id="七、续训-让模型-更懂某个世界" tabindex="-1">七、续训：让模型&quot;更懂某个世界&quot; <a class="header-anchor" href="#七、续训-让模型-更懂某个世界" aria-label="Permalink to &quot;七、续训：让模型&quot;更懂某个世界&quot;&quot;">​</a></h2><ul><li><strong>定义</strong>：Continued Pretraining——通用预训练完成后，用某领域<strong>大规模原始语料</strong>继续训练，补领域语言分布、术语体系和知识结构。用海量无标注文本，而非&quot;指令-答案&quot;样本。</li><li><strong>一句话区分</strong>：续训让模型&quot;更懂某个世界&quot;，微调让模型&quot;更会按要求做事&quot;。</li><li><strong>何时考虑</strong>：领域语言分布<strong>系统性缺失</strong>（不是差几个术语，而是整套表达&quot;不像这个行业的人&quot;），且 RAG 和微调都补不上。典型：法律/医疗/金融/代码语料领域适配、新语言适配。</li><li><strong>门槛</strong>：数据 GB~TB 级原始文本、算力远高于微调、业务收益要足够大——<strong>多数企业项目用不到</strong>，很多问题 <code>RAG + Prompt</code> 或 <code>RAG + 微调</code> 已能解决。</li><li><strong>误区</strong>：拿 SFT 问答对去续训（续训是语言建模）；把领域知识缺失全交给微调（模型连领域&quot;说话方式&quot;都不熟时微调不稳）；企业项目动不动就想续训。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>微调</th><th>续训</th></tr></thead><tbody><tr><td>训练目标</td><td>改行为方式</td><td>改知识/语言分布</td></tr><tr><td>数据形式</td><td>指令、对话、标签</td><td>大规模原始文本</td></tr><tr><td>依赖标注</td><td>强依赖</td><td>通常不依赖</td></tr><tr><td>数据规模</td><td>千~十万级</td><td>十万级~海量</td></tr><tr><td>算力成本</td><td>低到中</td><td>高</td></tr></tbody></table><p><strong>组合拳顺序不能反</strong>：通用基座 → 领域续训（补分布）→ 指令微调（对齐行为）→ RLHF/RLAIF。若先微调再做大规模续训，前面学到的行为模式会被冲掉。大多数应用团队的路径是：选好基座 → Prompt + RAG + 工作流/Agent 做应用层增强，行为稳定性或领域分布确实成瓶颈才进训练。</p><h2 id="八、智能体-大模型-工具-状态-执行流程" tabindex="-1">八、智能体：大模型 + 工具 + 状态 + 执行流程 <a class="header-anchor" href="#八、智能体-大模型-工具-状态-执行流程" aria-label="Permalink to &quot;八、智能体：大模型 + 工具 + 状态 + 执行流程&quot;">​</a></h2><blockquote><p>**智能体 = 大模型 + 工具 + 状态 + 执行流程。**智能体不是&quot;更强的大模型&quot;，而是能理解目标、决定下一步、选择是否调工具、接收结果、继续决策直到完成任务的系统。</p></blockquote><ul><li><strong>五大核心要素</strong>：LLM、记忆（Memory）、工具调用（Tools）、规划决策（Planning）、行动执行（Action）。</li><li><strong>与单纯大模型的本质区别</strong>：大模型负责&quot;生成回答&quot;（会告诉你&quot;可以查天气 API&quot;），智能体负责&quot;围绕目标持续决策并执行动作&quot;（真的去调 API，再把结果组织成回答）。</li><li><strong>何时需要</strong>：任务多步骤、要调外部工具（搜索/数据库/浏览器/发消息）、中间结果影响后续动作、需要状态管理/规划/重试/反思。</li></ul><blockquote><p>粗略区分：Prompt 是&quot;把问题问清楚&quot;，RAG 是&quot;先给模型补资料&quot;，Agent 是&quot;把一件事做完&quot;。</p></blockquote><h2 id="九、function-calling-与-mcp-模型决定-程序执行" tabindex="-1">九、Function Calling 与 MCP：模型决定，程序执行 <a class="header-anchor" href="#九、function-calling-与-mcp-模型决定-程序执行" aria-label="Permalink to &quot;九、Function Calling 与 MCP：模型决定，程序执行&quot;">​</a></h2><p><strong>Function Calling 五步闭环</strong>：① 告诉模型有哪些工具 + 用户说了什么 → ② 模型返回&quot;调哪个工具、传什么参数&quot;（<code>tool_calls</code>）→ ③ 我们的代码真正执行工具 → ④ 把工具结果塞回对话再请求模型 → ⑤ 模型根据结果生成最终回答。</p><blockquote><p>本质分工：**模型负责决定，程序负责执行。**模型并不会真的去调天气接口，它只输出&quot;应该调用哪个工具、传什么参数&quot;。</p></blockquote><p>核心形态（以 DeepSeek 为例，节选）——工具声明：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get_weather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;根据用户输入的城市信息，获取该城市的天气&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;parameters&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;object&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;properties&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;required&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } }}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>模型返回（只是&quot;提出调用请求&quot;，并未执行）：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tool_calls&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get_weather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">city</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">北京</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>FC 的不足</strong>：工具实现与复用成本高（与业务环境耦合重）；规范碎片化（各厂商格式、字段命名不一致）；可靠性依赖工具描述质量（描述不清就调错工具、传错参数）。</p><p><strong>MCP（Model Context Protocol）</strong>：把&quot;工具、资源、提示模板&quot;等能力按统一方式暴露出来的开放标准接口——像 AI 世界的 USB-C。注意：模型并不&quot;认识 MCP&quot;本身，它认识的是&quot;这次请求里有哪些可用工具&quot;。</p><table tabindex="0"><thead><tr><th></th><th>Function Calling</th><th>MCP</th></tr></thead><tbody><tr><td>是什么</td><td>模型调用工具的能力</td><td>一套标准化通讯协议</td></tr><tr><td>关注点</td><td>模型怎么表达&quot;我要调哪个工具&quot;</td><td>工具/资源怎么统一暴露、发现、复用</td></tr><tr><td>作用</td><td>让模型能调用外部能力</td><td>让外部能力被不同 AI 应用统一接入</td></tr><tr><td>适用层</td><td>模型调用层</td><td>应用接入层 / 工具生态层</td></tr></tbody></table><h2 id="十、工作流-vs-agent-固定用工作流-动态交-agent" tabindex="-1">十、工作流 vs Agent：固定用工作流，动态交 Agent <a class="header-anchor" href="#十、工作流-vs-agent-固定用工作流-动态交-agent" aria-label="Permalink to &quot;十、工作流 vs Agent：固定用工作流，动态交 Agent&quot;">​</a></h2><ul><li><strong>工作流（Workflow）</strong>：强调<strong>固定步骤和可控执行</strong>，把复杂任务拆成明确步骤按预设顺序执行（如：先分类 → 检索 → 生成 → 校验 → 输出）。</li><li><strong>判断标准</strong>：步骤固定、顺序明确、强调可控稳定 → 工作流；步骤不固定、需动态选工具和持续决策 → Agent。</li><li>真实系统常是两者结合：<strong>固定部分用工作流，动态部分再交给 Agent</strong>。例：电商问数 = 工作流主导（召回 → 生成 → 校验 → 执行）+ 大模型在关键节点参与决策。</li></ul><h2 id="十一、最值得记的口诀" tabindex="-1">十一、最值得记的口诀 <a class="header-anchor" href="#十一、最值得记的口诀" aria-label="Permalink to &quot;十一、最值得记的口诀&quot;">​</a></h2><ol><li><strong>三线判断</strong>：知识够不够（RAG）、行为稳不稳（微调）、流程会不会动（工作流/Agent）。</li><li><strong>选型口诀</strong>：先 Prompt → 再 RAG → 再微调 → 慎用续训；流程固定先工作流，流程开放再 Agent。</li><li><strong>RAG 补知识</strong>：运行时补上下文，改知识库即生效、可溯源；失败先修检索链路再看模型。</li><li><strong>微调改行为</strong>：前提是数据够 + 评测清楚；主流路线 LoRA/QLoRA；不承载高频变化的知识。</li><li><strong>续训补分布</strong>：GB~TB 级原始语料，多数企业项目用不到；组合训练先续训补分布、再微调对齐行为，顺序不能反。</li><li><strong>智能体做执行</strong>：不是更强的大模型，而是&quot;大模型 + 工具 + 状态 + 执行流程&quot;；Function Calling 是模型侧调用能力，MCP 是工具侧标准化暴露，模型永远只&quot;决定&quot;，&quot;执行&quot;在程序侧。</li></ol>`,49)])])}const k=s(n,[["render",r]]);export{g as __pageData,k as default};
